import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`property-analysis`,heroTitle:`Analyze any property in minutes`,heroSubtitle:`Perplexity Computer pulls the listing, runs comps, builds a rental model, and delivers a full investment analysis — automatically.`,inputUrlCta:`Analyze property`,inputUrlPlaceholder:`www.zillow.com...`,inputUrlPrefill:`Go to {url} and run a full property investment analysis. Pull the listing details, price history, and tax records. Find comparable sales and active listings within a half-mile radius. Build a rental income model with projected monthly cash flow, cap rate, and cash-on-cash return. Estimate rehab costs if applicable. Generate an investment summary with comps, rental projections, and a buy/pass recommendation.`,heroOverlaySteps:[`Pulling listing details, price history, and tax records`,`Finding comparable sales and active listings nearby`,`Building a rental model with cash flow and cap rate`,`Investment summary with comps and recommendation, ready to share`],generatingSteps:[`Visiting {url} to extract listing details, price history, and property data`,`Designing an agent to find comparable sales and rentals in the area`,`Configuring rental income model with cash flow and return projections`,`Setting up report generation for investment summary and comps package`],featureSectionTitle:`From listing to decision`,featureCardTitles:[`Pulls data from any listing site`,`Deliverables ready to present`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Zillow, Redfin, Realtor.com, county records — Computer reads the listing and researches the neighborhood so you don’t have to.`,`Comp packages. Rental models. Investment summaries. Computer delivers a full analysis you can share with partners or clients.`],capabilitySectionTitle:`Your underwriting team, on demand`,capabilitySectionSubtitle:`Paste a listing, get back a complete property analysis.`,capabilityCards:[{title:`Property Deep Dive`,description:`Computer pulls listing details, price history, tax records, and neighborhood data — all from a single link.`},{title:`Comp Analysis`,description:`Computer finds recent sales and active listings nearby, adjusts for differences, and builds a comp package.`},{title:`Rental Income Model`,description:`Computer estimates monthly rent, vacancy, expenses, and builds a cash flow model with cap rate and cash-on-cash return.`},{title:`Investment Summary`,description:`Computer generates a polished report with comps, projections, and a buy/pass recommendation — ready for your team.`},{title:`Knows Your Criteria`,description:`Computer remembers your buy box, return targets, and market preferences — so every analysis is tailored to you.`},{title:`New Listing Alerts`,description:`Computer monitors listings matching your criteria — and alerts you when a deal worth analyzing hits the market.`}]});export{t as default};
